"""Jalur JavaScript bagian 2: tipe data, prototype, type casting, struktur data, equality."""
from rb_js import J, JT, SX, SN
from mobile_lib import M, q

JS2 = [
M('Tipe data', 'Pemula',
  'Tujuh tipe primitif, object, typeof, prototype dan pewarisan prototipe, serta built-in objects.',
  ['Data Types', 'Primitive Types', 'string', 'number', 'bigint', 'boolean', 'undefined', 'null', 'Symbol', 'Object', 'typeof operator', 'Object Prototype', 'Prototypal Inheritance', 'Built-in Objects'], [
  J('Tipe primitif: string, number, boolean',
    ['JS punya <b>8 tipe data</b>: tujuh <b>primitif</b> (string, number, bigint, boolean, undefined, null, symbol) dan <b>object</b>. Nilai primitif bersifat <b>immutable</b> (tidak bisa diubah, hanya diganti) dan dibandingkan berdasarkan nilainya.',
     '<b>string</b>: teks dalam kutip satu, kutip dua, atau backtick (template literal, bisa multi-baris dan interpolasi). String immutable: metode seperti <code>toUpperCase()</code> mengembalikan string baru. <b>number</b>: satu tipe untuk bulat dan pecahan, berupa <b>64-bit floating point (IEEE 754)</b>, sehingga <code>0.1 + 0.2</code> tidak persis 0.3. Bilangan bulat aman hanya sampai <code>Number.MAX_SAFE_INTEGER</code> (2 pangkat 53 dikurangi 1). Ada nilai khusus <code>Infinity</code>, <code>-Infinity</code>, dan <code>NaN</code> (Not a Number, tetapi bertipe number).',
     '<b>boolean</b>: <code>true</code> atau <code>false</code>. Untuk uang di aplikasi nyata, hindari pecahan float: simpan dalam satuan terkecil (rupiah atau sen) sebagai bilangan bulat, lalu format dengan <code>Intl.NumberFormat</code>.'],
    "const produk = 'Kopi Gayo';\nconsole.log(produk.length, produk.toUpperCase(), produk[0]);\nconsole.log(`Stok ${produk}:\n  12 bungkus`);\n\nconsole.log(0.1 + 0.2, 0.1 + 0.2 === 0.3);\nconsole.log(Math.abs(0.1 + 0.2 - 0.3) < Number.EPSILON);  // cara membandingkan float\nconsole.log(Number.MAX_SAFE_INTEGER, 2 ** 53 + 1);\nconsole.log(10 / 0, -10 / 0, 'abc' * 2, typeof NaN);\nconsole.log(Number.isNaN('abc' * 2), (1234.5678).toFixed(2));\n\nconst rupiah = new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 });\nconsole.log(rupiah.format(1250000));\n\nconst lunas = true;\nconsole.log(typeof lunas, !lunas);",
    tb=[{'c': 'Tujuh tipe primitif', 'h': ['Tipe', 'Contoh', 'typeof'], 'r': [
      ['string', "'halo', `hai ${n}`", 'string'], ['number', '42, 3.14, NaN, Infinity', 'number'], ['bigint', '9007199254740993n', 'bigint'], ['boolean', 'true, false', 'boolean'],
      ['undefined', 'let x;', 'undefined'], ['null', 'null', 'object (bug historis)'], ['symbol', "Symbol('id')", 'symbol']]}],
    pts=['7 primitif + object.', 'Primitif immutable dan dibandingkan per nilai.', 'number = float 64-bit: hati-hati 0.1 + 0.2.', 'NaN bertipe number; cek dengan Number.isNaN.', 'Uang: bilangan bulat + Intl.NumberFormat.'],
    qs=[q('Hasil 0.1 + 0.2 === 0.3?', ['false', 'true', 'TypeError'], 0, 'Hasilnya 0.30000000000000004 karena representasi biner float.'),
        q('typeof NaN?', ['"number"', '"NaN"', '"undefined"'], 0, 'NaN adalah nilai number khusus.')],
    so=[SX('Hitung total belanja 3 barang Rp19.900, Rp45.500, Rp7.250 dengan PPN 11%, bulatkan ke rupiah terdekat, lalu tampilkan dengan format Rupiah Indonesia.', 'Math.round untuk membulatkan, Intl.NumberFormat id-ID currency IDR.',
           "const harga = [19900, 45500, 7250];\nlet subtotal = 0;\nfor (const h of harga) subtotal += h;\nconst total = Math.round(subtotal * 1.11);\nconst rp = new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 });\nconsole.log('Subtotal:', rp.format(subtotal));\nconsole.log('Total + PPN:', rp.format(total));")]),
  J('bigint, undefined, null, dan Symbol',
    ['<b>bigint</b> menyimpan bilangan bulat sebesar apa pun, ditulis dengan akhiran <code>n</code> (<code>123n</code>) atau <code>BigInt(\'123\')</code>. Cocok untuk ID 64-bit dari database atau API (misalnya ID tweet), kriptografi, dan perhitungan bulat besar. bigint tidak bisa dicampur langsung dengan number dalam operasi aritmetika.',
     '<b>undefined</b> berarti "belum diberi nilai": variabel tanpa nilai awal, parameter yang tidak dikirim, properti yang tidak ada, atau fungsi tanpa return. <b>null</b> berarti "sengaja kosong", diisi oleh programmer. <code>typeof null</code> menghasilkan <code>"object"</code>, bug sejak versi pertama yang dipertahankan demi kompatibilitas.',
     '<b>Symbol</b> adalah nilai unik yang dipakai sebagai kunci properti yang tidak akan bentrok. Dua <code>Symbol(\'id\')</code> selalu berbeda. Symbol bawaan (<b>well-known symbols</b>) seperti <code>Symbol.iterator</code> dan <code>Symbol.toPrimitive</code> dipakai untuk mengatur perilaku objek. Properti bersimbol tidak muncul di <code>for...in</code> maupun <code>JSON.stringify</code>.'],
    "const idPesanan = 9007199254740993n;\nconsole.log(idPesanan + 2n, typeof idPesanan);\nconsole.log(9007199254740993);                 // number kehilangan presisi\ntry { console.log(1n + 1); } catch (e) { console.log(e.name + ':', e.message); }\nconsole.log(5n / 2n, BigInt(10) ** 20n);       // pembagian bigint dibulatkan ke bawah\n\nlet alamat;\nconst user = { nama: 'Sari', telepon: null };\nconsole.log(alamat, user.email, user.telepon);\nconsole.log(typeof undefined, typeof null);\n\nconst ID = Symbol('id');\nconst a = Symbol('id');\nconsole.log(ID === a, ID.toString(), ID.description);\nconst akun = { nama: 'Sari', [ID]: 777 };\nconsole.log(akun[ID], Object.keys(akun), JSON.stringify(akun));",
    tb=[{'c': 'undefined vs null', 'h': ['Aspek', 'undefined', 'null'], 'r': [
      ['Arti', 'Belum ada nilai', 'Sengaja kosong'], ['Siapa yang mengisi', 'Biasanya engine', 'Programmer'], ['typeof', '"undefined"', '"object"'],
      ['Di JSON', 'Properti dihilangkan', 'Tetap null'], ['Number(x)', 'NaN', '0'], ['x == null', 'true', 'true']]}],
    pts=['bigint untuk bilangan bulat besar, akhiran n, tidak dicampur number.', 'undefined = belum ada; null = sengaja kosong.', 'typeof null === "object" adalah bug historis.', 'Symbol selalu unik; cocok untuk kunci tersembunyi.'],
    qs=[q('Hasil 1n + 1?', ['TypeError', '2n', '2'], 0, 'bigint dan number tidak bisa dicampur langsung.'),
        q('Nilai fungsi tanpa return saat dipanggil?', ['undefined', 'null', '0'], 0, 'Fungsi tanpa return mengembalikan undefined.')],
    so=[SX('Hitung 2 pangkat 64 dengan number dan dengan bigint, lalu cetak keduanya untuk melihat perbedaan presisi.', 'Gunakan 2 ** 64 dan 2n ** 64n.',
           "console.log('number:', 2 ** 64);\nconsole.log('bigint:', (2n ** 64n).toString());")]),
  J('Object dan operator typeof',
    ['<b>Object</b> adalah kumpulan pasangan <b>key-value</b> (properti). Key berupa string atau symbol; value bisa apa saja, termasuk fungsi (disebut <b>metode</b>). Array, fungsi, Date, Map, dan hampir semua hal selain primitif adalah object.',
     'Berbeda dengan primitif, object disimpan dan disalin <b>berdasarkan referensi</b>: dua variabel bisa menunjuk object yang sama, sehingga mengubah lewat satu variabel terlihat di variabel lain. Untuk menyalin, pakai spread <code>{...obj}</code> (dangkal) atau <code>structuredClone(obj)</code> (dalam).',
     '<code>typeof</code> mengembalikan string nama tipe. Jebakannya: <code>typeof null</code> adalah "object", array juga "object" (cek dengan <code>Array.isArray</code>), sedangkan fungsi menghasilkan "function". Untuk object bawaan, <code>instanceof</code> atau <code>Object.prototype.toString.call(x)</code> memberi info lebih tepat.'],
    "const produk = {\n  nama: 'Teh Melati',\n  harga: 12000,\n  'kode-sku': 'TM-01',             // key dengan tanda minus perlu kutip\n  info() { return `${this.nama} Rp${this.harga}`; },\n};\nconsole.log(produk.nama, produk['kode-sku'], produk.info());\nproduk.stok = 30;                   // tambah properti\ndelete produk['kode-sku'];          // hapus properti\nconsole.log(Object.keys(produk), 'harga' in produk);\n\nconst b = produk;                   // referensi yang sama\nb.harga = 15000;\nconsole.log(produk.harga, b === produk);\nconst salinan = { ...produk, harga: 9000 };\nconsole.log(produk.harga, salinan.harga, salinan === produk);\n\nfor (const x of ['teks', 1, 1n, true, undefined, null, Symbol(), {}, [], () => {}, new Date(0)]) {\n  console.log(String(typeof x).padEnd(9), Object.prototype.toString.call(x));\n}",
    tb=[{'c': 'Hasil typeof dan cara cek yang tepat', 'h': ['Nilai', 'typeof', 'Cek yang dianjurkan'], 'r': [
      ['[1, 2]', 'object', 'Array.isArray(x)'], ['null', 'object', 'x === null'], ['function', 'function', "typeof x === 'function'"],
      ['new Date()', 'object', 'x instanceof Date'], ['NaN', 'number', 'Number.isNaN(x)'], ['{ a: 1 }', 'object', "x !== null && typeof x === 'object'"]]}],
    pts=['Object = kumpulan key-value; metode adalah properti berisi fungsi.', 'Object disalin berdasarkan referensi.', 'Spread untuk salinan dangkal, structuredClone untuk salinan dalam.', 'typeof punya jebakan: null dan array.'],
    qs=[q('Output: const a = {n: 1}; const b = a; b.n = 2; console.log(a.n);', ['2', '1', 'undefined'], 0, 'a dan b menunjuk object yang sama.'),
        q('Cara tepat memeriksa sebuah nilai adalah array?', ['Array.isArray(x)', "typeof x === 'array'", 'x instanceof Object'], 0, 'typeof array menghasilkan "object".')],
    so=[SX('Buat object <code>mahasiswa</code> berisi nama, nim, dan array nilai. Salin dengan structuredClone, ubah nilai pertama di salinan, lalu buktikan object asli tidak berubah.', 'structuredClone menyalin sampai array di dalamnya.',
           "const mahasiswa = { nama: 'Dewi', nim: '2301001', nilai: [80, 90] };\nconst salinan = structuredClone(mahasiswa);\nsalinan.nilai[0] = 100;\nconsole.log('asli   :', mahasiswa.nilai);\nconsole.log('salinan:', salinan.nilai);")]),
  J('Prototype dan pewarisan prototipe',
    ['Setiap object di JS punya tautan tersembunyi ke object lain yang disebut <b>prototype</b> (dibaca dengan <code>Object.getPrototypeOf(obj)</code>, di konsol tampil sebagai <code>[[Prototype]]</code> atau <code>__proto__</code>). Saat properti tidak ditemukan di object, engine mencarinya di prototype, lalu prototype dari prototype, dan seterusnya sampai <code>null</code>. Rantai ini disebut <b>prototype chain</b>.',
     'Itulah sebabnya array kosong bisa memanggil <code>map</code>: metode itu tinggal di <code>Array.prototype</code>. <b>Pewarisan prototipe</b> (prototypal inheritance) berarti object mewarisi langsung dari object lain, bukan dari "cetakan" seperti di Java. Kata kunci <code>class</code> (ES2015) hanyalah sintaks yang lebih rapi di atas mekanisme prototype ini (<b>syntactic sugar</b>).',
     'Buat object dengan prototype tertentu memakai <code>Object.create(proto)</code>. Fungsi konstruktor menyimpan metode bersama di <code>Fungsi.prototype</code>. Jangan menambah metode ke prototype bawaan (<code>Array.prototype.x = ...</code>): praktik ini disebut <b>monkey patching</b> dan bisa bentrok dengan fitur bahasa di masa depan.'],
    "const hewan = {\n  bersuara() { return `${this.nama} bersuara: ${this.suara}`; },\n};\nconst kucing = Object.create(hewan);   // prototype kucing = hewan\nkucing.nama = 'Oyen';\nkucing.suara = 'meong';\nconsole.log(kucing.bersuara());\nconsole.log(Object.getPrototypeOf(kucing) === hewan, Object.hasOwn(kucing, 'bersuara'));\n\n// fungsi konstruktor (gaya sebelum class)\nfunction Akun(pemilik, saldo) {\n  this.pemilik = pemilik;\n  this.saldo = saldo;\n}\nAkun.prototype.setor = function (n) { this.saldo += n; return this.saldo; };\nconst a1 = new Akun('Rudi', 1000);\nconst a2 = new Akun('Tari', 500);\nconsole.log(a1.setor(250), a1.setor === a2.setor);   // metode dibagi bersama\n\n// rantai prototype sebuah array\nlet p = [1, 2];\nconst rantai = [];\nwhile (p) { p = Object.getPrototypeOf(p); rantai.push(p === null ? 'null' : p.constructor.name + '.prototype'); }\nconsole.log(rantai.join(' -> '));",
    tb=[{'c': 'Istilah prototype', 'h': ['Istilah', 'Arti'], 'r': [
      ['[[Prototype]]', 'Tautan internal object ke prototype-nya'], ['Object.getPrototypeOf(o)', 'Cara resmi membaca prototype'], ['F.prototype', 'Object yang menjadi prototype bagi hasil new F()'],
      ['Object.create(p)', 'Membuat object baru dengan prototype p'], ['Object.hasOwn(o, k)', 'Cek properti milik sendiri (bukan warisan)'], ['Prototype chain', 'Urutan pencarian properti sampai null']]}],
    pts=['Setiap object punya prototype; pencarian properti menelusuri prototype chain.', 'Metode bawaan tinggal di prototype seperti Array.prototype.', 'class adalah syntactic sugar di atas prototype.', 'Jangan memodifikasi prototype bawaan.'],
    qs=[q('Kenapa [].map bisa dipanggil padahal array kosong tidak punya properti map sendiri?', ['map ditemukan di Array.prototype lewat prototype chain', 'Engine menyalin map ke setiap array', 'map adalah fungsi global'], 0, 'Pencarian properti naik ke prototype.'),
        q('Ujung akhir setiap prototype chain?', ['null', 'Object', 'undefined'], 0, 'Object.prototype punya prototype null.')],
    so=[SX('Buat object <code>kendaraan</code> dengan metode <code>info()</code> yang mencetak merek dan roda. Buat <code>motor</code> dengan Object.create(kendaraan), isi merek dan roda = 2, lalu panggil info().', 'Gunakan this di dalam metode info.',
           "const kendaraan = {\n  info() { return `${this.merek} beroda ${this.roda}`; },\n};\nconst motor = Object.create(kendaraan);\nmotor.merek = 'Honda Beat';\nmotor.roda = 2;\nconsole.log(motor.info());\nconsole.log(Object.hasOwn(motor, 'info'));")]),
  J('Built-in objects',
    ['JS menyediakan banyak <b>built-in objects</b> (objek bawaan standar) yang siap pakai tanpa import. Kelompok pentingnya: <b>dasar</b> (Object, Function, Boolean, Symbol, Error), <b>angka dan tanggal</b> (Number, BigInt, Math, Date), <b>teks</b> (String, RegExp), <b>koleksi</b> (Array, Map, Set, WeakMap, WeakSet, typed arrays), <b>terstruktur</b> (JSON, ArrayBuffer), <b>kontrol abstraksi</b> (Promise, generator), <b>refleksi</b> (Reflect, Proxy), dan <b>internasionalisasi</b> (Intl).',
     'Jangan tertukar dengan <b>Web API</b> (document, fetch, localStorage, setTimeout) yang disediakan browser, atau API Node (fs, process). Built-in objects adalah bagian dari bahasa itu sendiri sehingga tersedia di semua lingkungan. Objek global tingkat atas bisa diakses lewat <code>globalThis</code>.',
     'Untuk tanggal, <code>Date</code> punya banyak kekurangan (bulan dimulai dari 0, zona waktu membingungkan). Proposal <b>Temporal</b> sedang menggantikannya dan sudah mulai tersedia di browser baru; sampai merata, banyak tim memakai pustaka seperti date-fns atau Day.js.'],
    "console.log(Math.max(3, 9, 4), Math.round(2.5), Math.floor(-2.5), Math.trunc(-2.5));\nconsole.log(Number.parseFloat('12.5kg'), Number.isInteger(5.0), (255).toString(16));\nconsole.log('ruang-kode'.split('-'), '  spasi  '.trim(), 'ab'.repeat(3), 'Kopi'.padStart(6, '*'));\n\nconst d = new Date(Date.UTC(2026, 7, 17, 3, 0));   // bulan 7 = Agustus (dimulai 0)\nconsole.log(d.toISOString());\nconsole.log(new Intl.DateTimeFormat('id-ID', { dateStyle: 'full', timeZone: 'Asia/Jakarta' }).format(d));\n\nconsole.log(/^08\\d{8,11}$/.test('081234567890'));    // RegExp: nomor HP Indonesia\nconsole.log(JSON.stringify({ a: [1, 2] }), Reflect.ownKeys({ x: 1, [Symbol('s')]: 2 }));\nconsole.log(new Intl.NumberFormat('id-ID').format(1234567.891));\nconsole.log(typeof globalThis.Math, typeof globalThis.setTimeout);",
    tb=[{'c': 'Kelompok built-in objects', 'h': ['Kelompok', 'Contoh', 'Kegunaan'], 'r': [
      ['Dasar', 'Object, Function, Error, Symbol', 'Fondasi bahasa'], ['Angka & tanggal', 'Number, BigInt, Math, Date', 'Hitung dan waktu'], ['Teks', 'String, RegExp', 'Olah teks dan pola'],
      ['Koleksi berindeks', 'Array, Int8Array, Float64Array', 'Data berurutan'], ['Koleksi berkunci', 'Map, Set, WeakMap, WeakSet', 'Data unik dan pemetaan'],
      ['Data terstruktur', 'JSON, ArrayBuffer, DataView', 'Pertukaran dan biner'], ['Asinkron', 'Promise, AsyncFunction', 'Operasi di masa depan'],
      ['Refleksi', 'Reflect, Proxy', 'Metaprogramming'], ['Intl', 'NumberFormat, DateTimeFormat, Collator', 'Format sesuai bahasa dan negara']]}],
    pts=['Built-in objects tersedia di semua lingkungan tanpa import.', 'Web API (document, fetch) bukan bagian dari bahasa.', 'Bulan di Date dimulai dari 0.', 'Intl untuk format angka dan tanggal lokal.'],
    qs=[q('Mana yang termasuk built-in object JavaScript, bukan Web API?', ['Math', 'document', 'localStorage'], 0, 'document dan localStorage disediakan browser.'),
        q('new Date(2026, 0, 1) adalah tanggal?', ['1 Januari 2026', '1 Februari 2026', '31 Desember 2025'], 0, 'Bulan 0 = Januari.')],
    so=[SX('Validasi tiga alamat email dengan RegExp sederhana (ada teks, @, domain, titik, akhiran minimal 2 huruf) dan cetak hasilnya.', 'Pola contoh: /^[^\\s@]+@[^\\s@]+\\.[a-z]{2,}$/i',
           "const pola = /^[^\\s@]+@[^\\s@]+\\.[a-z]{2,}$/i;\nfor (const e of ['rina@kampus.ac.id', 'budi@', 'tari @mail.com']) {\n  console.log(e.padEnd(18), pola.test(e) ? 'valid' : 'tidak valid');\n}")]),
]),

M('Type casting: konversi dan koersi', 'Pemula',
  'Beda type conversion dan type coercion, konversi eksplisit ke string, number, boolean, serta aturan koersi implisit.',
  ['Type Casting', 'Type Conversion vs Coercion', 'Explicit Type Casting', 'Implicit Type Casting'], [
  J('Konversi eksplisit',
    ['<b>Type conversion</b> (atau <b>explicit casting</b>) adalah mengubah tipe dengan sengaja memakai fungsi. <b>Type coercion</b> (atau <b>implicit casting</b>) adalah konversi otomatis yang dilakukan engine saat operator bertemu tipe berbeda. Prinsip kode profesional: <b>buat konversi eksplisit</b> agar maksudnya jelas.',
     'Ke <b>string</b>: <code>String(x)</code>, <code>x.toString()</code> (gagal pada null/undefined), atau template literal. Ke <b>number</b>: <code>Number(x)</code> mengubah seluruh string (gagal = NaN), sedangkan <code>parseInt(x, 10)</code> dan <code>parseFloat(x)</code> membaca dari awal sampai karakter tidak valid. Selalu beri radix 10 pada parseInt. Unary <code>+x</code> sama dengan Number(x).',
     'Ke <b>boolean</b>: <code>Boolean(x)</code> atau <code>!!x</code>. Hanya ada 8 nilai <b>falsy</b>: <code>false</code>, <code>0</code>, <code>-0</code>, <code>0n</code>, <code>""</code>, <code>null</code>, <code>undefined</code>, <code>NaN</code>. Selain itu <b>truthy</b>, termasuk <code>"0"</code>, <code>"false"</code>, <code>[]</code>, dan <code>{}</code>.'],
    "const input = '12500';                         // nilai dari form selalu string\nconsole.log(Number(input) + 500, typeof Number(input));\nconsole.log(Number(''), Number('  42 '), Number('12px'), Number(null), Number(undefined), Number(true));\nconsole.log(parseInt('12px', 10), parseFloat('3.75kg'), parseInt('0x1F', 16), parseInt('101', 2));\nconsole.log(+'7', +'', +[], +{});\n\nconsole.log(String(123), (255).toString(2), String(null), `${[1, 2]}`);\n\nconst nilai = [false, 0, -0, 0n, '', null, undefined, NaN, '0', 'false', [], {}, ' '];\nconsole.log(nilai.map(v => (Object.is(v, -0) ? '-0' : typeof v === 'bigint' ? '0n' : Number.isNaN(v) ? 'NaN' : JSON.stringify(v) ?? String(v)) + '=' + Boolean(v)).join('  '));",
    tb=[{'c': 'Fungsi konversi', 'h': ['Input', 'Number()', 'parseInt(x, 10)', 'Boolean()'], 'r': [
      ["'42'", '42', '42', 'true'], ["'42px'", 'NaN', '42', 'true'], ["''", '0', 'NaN', 'false'], ["'  7 '", '7', '7', 'true'],
      ['null', '0', 'NaN', 'false'], ['undefined', 'NaN', 'NaN', 'false'], ['true', '1', 'NaN', 'true'], ['[]', '0', 'NaN', 'true']]}],
    pts=['Conversion = sengaja; coercion = otomatis oleh engine.', 'Number() ketat; parseInt/parseFloat membaca awalan.', 'parseInt selalu dengan radix 10.', 'Hafalkan 8 nilai falsy; sisanya truthy.'],
    qs=[q('Number("12px")?', ['NaN', '12', '0'], 0, 'Number membaca seluruh string.'),
        q('Nilai yang truthy?', ['"0"', '0', '""'], 0, 'String tidak kosong selalu truthy.'),
        q('Number(null) dan Number(undefined)?', ['0 dan NaN', 'NaN dan NaN', '0 dan 0'], 0, 'Perbedaan klasik null vs undefined.')],
    so=[SX('Input dari form: <code>["15", "7.5", "abc", "", "20kg"]</code>. Jumlahkan hanya yang merupakan angka valid menurut Number() dan bukan string kosong.', 'Lewati jika x.trim() === "" atau Number.isNaN(Number(x)).',
           "const input = ['15', '7.5', 'abc', '', '20kg'];\nlet total = 0;\nfor (const x of input) {\n  if (x.trim() === '' || Number.isNaN(Number(x))) {\n    console.log('lewati:', JSON.stringify(x));\n    continue;\n  }\n  total += Number(x);\n}\nconsole.log('total:', total);")]),
  J('Koersi implisit',
    ['Koersi terjadi saat operator menerima tipe yang tidak sesuai. Aturan intinya: operator <code>+</code> dengan <b>salah satu operand string</b> melakukan penggabungan string; operator aritmetika lain (<code>- * / %</code>) mengubah operand menjadi number; konteks kondisi (<code>if</code>, <code>&&</code>, <code>||</code>, <code>!</code>) mengubah ke boolean; <code>==</code> melakukan koersi sebelum membandingkan.',
     'Object dikonversi ke primitif lewat <b>ToPrimitive</b>: memanggil <code>[Symbol.toPrimitive]</code> jika ada, lalu <code>valueOf()</code> atau <code>toString()</code> tergantung hint. Itu sebabnya <code>[] + {}</code> menghasilkan <code>"[object Object]"</code> dan <code>[1,2] + [3]</code> menghasilkan <code>"1,23"</code>.',
     'Bug koersi yang sering terjadi di produksi: menjumlahkan nilai input form (<code>"10" + 5 = "105"</code>), membandingkan string angka (<code>"10" &lt; "9"</code> bernilai true karena dibandingkan per karakter), dan memakai <code>||</code> untuk default padahal 0 adalah nilai sah. TypeScript dan ESLint (<code>eqeqeq</code>) membantu mencegahnya.'],
    "console.log('10' + 5, '10' - 5, '10' * '2', '10' / 'a');\nconsole.log(5 + 5 + '5', '5' + 5 + 5);       // kiri ke kanan\nconsole.log(true + 1, null + 1, undefined + 1);\nconsole.log([] + [], [] + {}, [1, 2] + [3]);\nconsole.log('10' < '9', 10 < 9, '10' < 9);      // string vs number\n\nconst harga = {\n  nilai: 15000,\n  [Symbol.toPrimitive](hint) {\n    return hint === 'number' ? this.nilai : `Rp${this.nilai}`;\n  },\n};\nconsole.log(+harga, `${harga}`, harga * 2);\n\nconst diskon = 0;\nconsole.log(diskon || 10, diskon ?? 10);       // || salah untuk nilai 0\nif ('0') console.log(\"'0' truthy, masuk if\");",
    tb=[{'c': 'Aturan koersi operator', 'h': ['Konteks', 'Dikonversi ke', 'Contoh'], 'r': [
      ['a + b, salah satu string', 'String', "'3' + 4 = '34'"], ['- * / % **', 'Number', "'6' / '2' = 3"], ['Unary +', 'Number', "+'5' = 5"],
      ['if, !, &&, ||, ? :', 'Boolean', "if ('') tidak masuk"], ['== antar tipe berbeda', 'Number (umumnya)', "'1' == 1 true"], ['Template literal', 'String', '`${[1,2]}` = "1,2"'],
      ['< > <= >= dua string', 'Tetap string, leksikografis', "'10' < '9' true"]]}],
    pts=['+ dengan string = gabung; operator lain = number.', 'Object diubah ke primitif lewat Symbol.toPrimitive/valueOf/toString.', 'Bandingkan string angka setelah dikonversi ke number.', 'Pakai ?? untuk default jika 0 atau "" valid.'],
    qs=[q("Hasil '5' + 5 + 5?", ["'555'", "'510'", '15'], 0, 'Dari kiri: "5"+5 = "55", lalu "55"+5.'),
        q("Hasil '10' < '9'?", ['true', 'false', 'NaN'], 0, 'Dua string dibandingkan per karakter: "1" < "9".')],
    so=[SX('Urutkan <code>["100", "25", "3"]</code> secara numerik. Tunjukkan dulu hasil sort() tanpa pembanding, lalu hasil yang benar.', 'sort() bawaan membandingkan sebagai string; pakai (a, b) => a - b.',
           "const data = ['100', '25', '3'];\nconsole.log([...data].sort());\nconsole.log([...data].sort((a, b) => a - b));\nconsole.log(data.map(Number).sort((a, b) => a - b));")]),
]),

M('Struktur data', 'Menengah',
  'Array dan metodenya, typed arrays, Map, WeakMap, Set, WeakSet, dan JSON sebagai data terstruktur.',
  ['Data Structures', 'Indexed Collections', 'Arrays', 'Typed Arrays', 'Keyed Collections', 'Map', 'WeakMap', 'Set', 'WeakSet', 'Structured Data', 'JSON'], [
  J('Array: dasar dan mutasi',
    ['<b>Array</b> adalah koleksi berindeks mulai dari 0. Panjangnya dinamis dan isinya boleh campuran tipe, walau di praktik sebaiknya satu jenis. <code>length</code> selalu indeks terbesar + 1. Gunakan <code>at(-1)</code> untuk elemen terakhir.',
     'Metode <b>mutating</b> mengubah array asli: <code>push/pop</code> (ujung belakang), <code>unshift/shift</code> (depan, lebih lambat karena menggeser indeks), <code>splice</code> (sisip/hapus di tengah), <code>sort</code>, <code>reverse</code>, <code>fill</code>. Di React dan Redux, state tidak boleh dimutasi, jadi pakai versi <b>non-mutating</b>: <code>slice</code>, <code>concat</code>, spread <code>[...a]</code>, serta ES2023 <code>toSorted</code>, <code>toReversed</code>, <code>toSpliced</code>, <code>with</code>.',
     'Pencarian: <code>includes</code> (ada atau tidak), <code>indexOf</code> (posisi), <code>find/findIndex</code> (dengan kondisi), <code>findLast</code>. Cek array kosong dengan <code>arr.length === 0</code>, karena array kosong tetap truthy.'],
    "const antrean = ['Ani', 'Budi'];\nantrean.push('Citra');               // tambah di belakang\nantrean.unshift('Dodi');             // tambah di depan\nconsole.log(antrean, antrean.length, antrean.at(-1));\nconsole.log('dilayani:', antrean.shift(), '| sisa:', antrean);\nantrean.splice(1, 1, 'Eko', 'Fani'); // dari indeks 1 hapus 1, sisipkan 2\nconsole.log(antrean);\n\nconst nilai = [70, 95, 82];\nconst urut = nilai.toSorted((a, b) => b - a);   // tidak mengubah asli\nconst ganti = nilai.with(0, 75);\nconsole.log(nilai, urut, ganti);\nconsole.log(nilai.includes(95), nilai.indexOf(82), nilai.find(n => n > 80), nilai.findLast(n => n > 80));\nconsole.log(Array.from({ length: 5 }, (_, i) => i * i), Array.of(7), new Array(3).fill(0));\nconsole.log([[1, 2], [3, [4]]].flat(Infinity), Boolean([]));",
    tb=[{'c': 'Metode mutating vs non-mutating', 'h': ['Tujuan', 'Mengubah asli', 'Tidak mengubah asli'], 'r': [
      ['Tambah di akhir', 'push(x)', '[...a, x] atau concat'], ['Hapus/sisip di tengah', 'splice(i, n, ...)', 'toSpliced(i, n, ...)'], ['Urutkan', 'sort(fn)', 'toSorted(fn)'],
      ['Balik', 'reverse()', 'toReversed()'], ['Ganti satu indeks', 'a[i] = x', 'with(i, x)'], ['Ambil potongan', '-', 'slice(awal, akhir)']]}],
    pts=['Indeks mulai 0; at(-1) untuk elemen terakhir.', 'Bedakan metode mutating dan non-mutating.', 'toSorted, toReversed, toSpliced, with (ES2023) untuk state immutable.', 'Array kosong itu truthy; cek length.'],
    qs=[q('Metode yang TIDAK mengubah array asli?', ['slice', 'splice', 'sort'], 0, 'slice mengembalikan salinan potongan.'),
        q('Cara aman mengurutkan state array di React?', ['state.toSorted(fn) atau [...state].sort(fn)', 'state.sort(fn)', 'state.reverse()'], 0, 'Jangan mutasi state.')],
    so=[SX('Daftar tugas <code>["desain", "coding", "testing"]</code>: sisipkan "review" sebelum "testing", hapus "desain", dan tampilkan hasil akhirnya tanpa memakai push.', 'splice(indeks, jumlahHapus, ...sisipan).',
           "const tugas = ['desain', 'coding', 'testing'];\ntugas.splice(tugas.indexOf('testing'), 0, 'review');\ntugas.splice(tugas.indexOf('desain'), 1);\nconsole.log(tugas);")]),
  J('Array: map, filter, reduce, dan kawan-kawan',
    ['Metode <b>higher-order</b> menerima fungsi <b>callback</b> dan menjadi inti gaya fungsional JS. <code>map</code> mengubah setiap elemen (panjang tetap), <code>filter</code> menyaring, <code>reduce</code> mengakumulasi menjadi satu nilai, <code>forEach</code> hanya menjalankan efek (tanpa nilai kembali), <code>some/every</code> mengecek kondisi, <code>flatMap</code> memetakan lalu meratakan satu tingkat.',
     'Metode ini bisa <b>dirantai</b> (method chaining) sehingga transformasi data terbaca seperti pipeline. Untuk data sangat besar, satu <code>reduce</code> atau loop biasa bisa lebih hemat dibanding rantai panjang karena setiap tahap membuat array baru.',
     'Selalu beri <b>nilai awal</b> pada <code>reduce</code>; tanpa itu, reduce pada array kosong melempar TypeError. Untuk mengelompokkan data, ES2024 menyediakan <code>Object.groupBy</code> dan <code>Map.groupBy</code>.'],
    "const pesanan = [\n  { id: 1, kota: 'Bandung', total: 125000, status: 'lunas' },\n  { id: 2, kota: 'Jakarta', total: 89000, status: 'batal' },\n  { id: 3, kota: 'Bandung', total: 230000, status: 'lunas' },\n  { id: 4, kota: 'Medan', total: 54000, status: 'lunas' },\n];\nconst lunas = pesanan.filter(p => p.status === 'lunas');\nconsole.log(lunas.map(p => p.id));\nconst omzet = lunas.reduce((acc, p) => acc + p.total, 0);\nconsole.log('omzet:', omzet.toLocaleString('id-ID'));\nconsole.log(pesanan.some(p => p.total > 200000), pesanan.every(p => p.total > 50000));\n\nconst perKota = Object.groupBy(lunas, p => p.kota);\nfor (const [kota, daftar] of Object.entries(perKota)) {\n  console.log(kota.padEnd(8), daftar.reduce((a, p) => a + p.total, 0));\n}\nconst tag = [['js', 'web'], ['node'], []].flatMap(t => t);\nconsole.log(tag, [].reduce((a, b) => a + b, 0));",
    tb=[{'c': 'Metode iterasi array', 'h': ['Metode', 'Mengembalikan', 'Pakai untuk'], 'r': [
      ['map(fn)', 'Array baru, panjang sama', 'Ubah bentuk setiap item'], ['filter(fn)', 'Array baru, mungkin lebih pendek', 'Saring'], ['reduce(fn, awal)', 'Satu nilai apa saja', 'Total, objek indeks, gabung'],
      ['forEach(fn)', 'undefined', 'Efek samping (log, kirim)'], ['find(fn)', 'Elemen pertama atau undefined', 'Cari satu'], ['some / every', 'boolean', 'Ada yang / semua memenuhi'],
      ['flatMap(fn)', 'Array rata satu tingkat', 'Satu item jadi banyak'], ['Object.groupBy(a, fn)', 'Object kelompok', 'Grouping (ES2024)']]}],
    pts=['map ubah, filter saring, reduce akumulasi.', 'Rantai metode membentuk pipeline data.', 'reduce selalu dengan nilai awal.', 'Object.groupBy untuk pengelompokan.'],
    qs=[q('Hasil [1, 2, 3].map(x => x * 2).filter(x => x > 2)?', ['[4, 6]', '[2, 4, 6]', '[6]'], 0, 'map menghasilkan [2,4,6], filter menyisakan [4,6].'),
        q('Nilai kembali forEach?', ['undefined', 'Array baru', 'Jumlah elemen'], 0, 'forEach hanya untuk efek samping.')],
    so=[SX('Dari data nilai <code>[{nama:"Ani",n:88},{nama:"Budi",n:62},{nama:"Citra",n:75},{nama:"Dodi",n:91}]</code>, cetak nama yang lulus (n &gt;= 70) diurutkan dari nilai tertinggi, dan rata-rata semua nilai dengan 1 desimal.', 'filter, toSorted, map; reduce untuk jumlah lalu bagi length.',
           "const data = [{ nama: 'Ani', n: 88 }, { nama: 'Budi', n: 62 }, { nama: 'Citra', n: 75 }, { nama: 'Dodi', n: 91 }];\nconst lulus = data.filter(d => d.n >= 70).toSorted((a, b) => b.n - a.n).map(d => d.nama);\nconsole.log('Lulus:', lulus.join(', '));\nconst rata = data.reduce((a, d) => a + d.n, 0) / data.length;\nconsole.log('Rata-rata:', rata.toFixed(1));")]),
  J('Typed Arrays',
    ['<b>Typed arrays</b> adalah tampilan berjenis (view) di atas blok memori mentah <code>ArrayBuffer</code>. Setiap elemen punya ukuran tetap: <code>Uint8Array</code> (0 sampai 255), <code>Int16Array</code>, <code>Float32Array</code>, <code>Float64Array</code>, <code>BigInt64Array</code>, dan lainnya. Panjangnya tetap dan semua elemen satu tipe.',
     'Dipakai saat bekerja dengan <b>data biner</b> dan performa tinggi: piksel gambar di Canvas (<code>Uint8ClampedArray</code>), audio (Web Audio), WebGL/WebGPU, file yang diunggah (<code>file.arrayBuffer()</code>), WebSocket biner, kriptografi (<code>crypto.getRandomValues</code>), dan WebAssembly.',
     'Nilai yang keluar rentang akan <b>dibungkus (overflow)</b>, kecuali Uint8ClampedArray yang dipotong ke 0 sampai 255. Beberapa view bisa berbagi satu buffer, dan <code>DataView</code> membaca/menulis angka dengan urutan byte (<b>endianness</b>) tertentu, misalnya saat mengurai format file atau protokol jaringan.'],
    "const buf = new ArrayBuffer(8);              // 8 byte memori\nconst u8 = new Uint8Array(buf);\nconst u32 = new Uint32Array(buf);           // view lain pada buffer yang sama\nu32[0] = 0x01020304;\nconsole.log(u8, buf.byteLength);            // urutan byte little-endian\n\nconst piksel = new Uint8Array([250, 10]);\npiksel[0] += 10;                            // overflow: 260 menjadi 4\nconst clamp = new Uint8ClampedArray([250, 10]);\nclamp[0] += 10;                             // dipotong ke 255\nclamp[1] = -20;                             // dipotong ke 0\nconsole.log(piksel, clamp);\n\nconst f = Float32Array.from([0.1, 0.5]);\nconsole.log(f[0], f.BYTES_PER_ELEMENT, Array.isArray(f));\n\nconst dv = new DataView(new ArrayBuffer(4));\ndv.setUint16(0, 0xCAFE);                    // big-endian (bawaan DataView)\nconsole.log(dv.getUint8(0).toString(16), dv.getUint8(1).toString(16));\nconsole.log(new TextEncoder().encode('Hai'), new TextDecoder().decode(new Uint8Array([79, 75])));",
    tb=[{'c': 'Jenis typed array', 'h': ['Tipe', 'Byte per elemen', 'Rentang / pemakaian'], 'r': [
      ['Int8Array', '1', '-128 sampai 127'], ['Uint8Array', '1', '0 sampai 255, data biner umum'], ['Uint8ClampedArray', '1', '0 sampai 255 dipotong, piksel Canvas'],
      ['Int16Array / Uint16Array', '2', 'Audio PCM 16-bit'], ['Int32Array / Uint32Array', '4', 'Indeks, hash'], ['Float32Array', '4', 'WebGL, ML'], ['Float64Array', '8', 'Presisi seperti number'], ['BigInt64Array', '8', 'Bilangan bulat 64-bit']]}],
    pts=['Typed array = view berjenis di atas ArrayBuffer.', 'Panjang tetap, satu tipe, sangat cepat.', 'Dipakai untuk gambar, audio, file, WebGL, Wasm.', 'Overflow dibungkus; Clamped dipotong.'],
    qs=[q('Nilai Uint8Array setelah elemen 250 ditambah 10?', ['4', '255', '260'], 0, '260 mod 256 = 4.'),
        q('Typed array yang dipakai data piksel Canvas?', ['Uint8ClampedArray', 'Float64Array', 'BigInt64Array'], 0, 'Nilai RGBA 0 sampai 255.')],
    so=[SX('Buat Uint8ClampedArray berisi satu piksel RGBA [200, 120, 40, 255]. Naikkan kecerahan R, G, B sebesar 80 dan cetak hasilnya.', 'Loop indeks 0 sampai 2; nilai di atas 255 otomatis dipotong.',
           "const px = new Uint8ClampedArray([200, 120, 40, 255]);\nfor (let i = 0; i < 3; i++) px[i] += 80;\nconsole.log(px);")]),
  J('Map dan Set',
    ['<b>Map</b> adalah koleksi key-value di mana <b>key bisa tipe apa saja</b> (object, fungsi, number), urutan sisip terjaga, ukurannya tersedia lewat <code>size</code>, dan dioptimalkan untuk tambah/hapus yang sering. Gunakan Map untuk kamus dinamis (cache, indeks berdasarkan ID); gunakan object biasa untuk struktur data dengan field tetap.',
     '<b>Set</b> menyimpan <b>nilai unik</b>. Cara tercepat menghapus duplikat: <code>[...new Set(arr)]</code>. Pengecekan <code>has</code> pada Set rata-rata O(1), jauh lebih cepat daripada <code>includes</code> pada array besar yang O(n). ES2025 menambahkan operasi himpunan: <code>union</code>, <code>intersection</code>, <code>difference</code>, <code>symmetricDifference</code>, <code>isSubsetOf</code>.',
     'Keduanya iterable, jadi bisa dipakai di <code>for...of</code>, spread, dan destructuring. Kesetaraan key memakai algoritma <b>SameValueZero</b>: NaN dianggap sama dengan NaN, dan dua object berbeda tetap dua key berbeda walau isinya sama.'],
    "const stok = new Map();\nstok.set('kopi', 12).set('teh', 30).set('gula', 0);\nconsole.log(stok.get('teh'), stok.has('susu'), stok.size);\nstok.delete('gula');\nfor (const [barang, jml] of stok) console.log(barang, '=>', jml);\n\nconst objKey = { id: 7 };\nconst sesi = new Map([[objKey, 'aktif']]);       // object sebagai key\nconsole.log(sesi.get(objKey), sesi.get({ id: 7 }));\nconsole.log(Object.fromEntries(stok), new Map(Object.entries({ a: 1 })));\n\nconst kunjungan = ['bdg', 'jkt', 'bdg', 'mdn', 'jkt'];\nconst unik = new Set(kunjungan);\nconsole.log(unik, unik.size, [...unik]);\nconsole.log(new Set([NaN, NaN, 0, -0]).size);\n\nconst kelasA = new Set(['Ani', 'Budi', 'Citra']);\nconst kelasB = new Set(['Budi', 'Dodi']);\nconsole.log([...kelasA.intersection(kelasB)], [...kelasA.union(kelasB)], [...kelasA.difference(kelasB)]);",
    tb=[{'c': 'Object vs Map, Array vs Set', 'h': ['Aspek', 'Object', 'Map'], 'r': [
      ['Tipe key', 'String/symbol', 'Apa saja'], ['Ukuran', 'Object.keys(o).length', 'map.size'], ['Urutan', 'Aturan khusus (angka dulu)', 'Urutan sisip'],
      ['Iterasi langsung', 'Tidak (perlu Object.entries)', 'Ya, for...of'], ['Risiko key bawaan', 'Ada (toString, __proto__)', 'Tidak ada'], ['Cocok untuk', 'Record dengan field tetap, JSON', 'Kamus dinamis, cache']]},
        {'c': 'Kapan memakai Set', 'h': ['Kebutuhan', 'Array', 'Set'], 'r': [
      ['Duplikat', 'Boleh', 'Otomatis dibuang'], ['Cek keberadaan', 'includes O(n)', 'has O(1)'], ['Akses indeks', 'Ya', 'Tidak'], ['Operasi himpunan', 'Manual', 'union, intersection (ES2025)']]}],
    pts=['Map: key tipe apa saja, size, urutan sisip.', 'Set: nilai unik, has O(1).', '[...new Set(arr)] menghapus duplikat.', 'Kesetaraan key memakai SameValueZero.'],
    qs=[q('Cara cepat membuang duplikat dari array?', ['[...new Set(arr)]', 'arr.unique()', 'new Map(arr)'], 0, 'Set hanya menyimpan nilai unik.'),
        q('map.get({id: 7}) jika key yang disimpan adalah object lain dengan isi sama?', ['undefined', 'Nilainya', 'TypeError'], 0, 'Object dibandingkan berdasarkan referensi.')],
    so=[SX('Hitung frekuensi kata pada kalimat "kopi susu kopi gula kopi susu" memakai Map, lalu cetak kata dan jumlahnya diurutkan dari yang terbanyak.', 'map.set(k, (map.get(k) ?? 0) + 1), lalu [...map].sort.',
           "const kata = 'kopi susu kopi gula kopi susu'.split(' ');\nconst frek = new Map();\nfor (const k of kata) frek.set(k, (frek.get(k) ?? 0) + 1);\nfor (const [k, n] of [...frek].sort((a, b) => b[1] - a[1])) console.log(k, n);")]),
  J('WeakMap dan WeakSet',
    ['<b>WeakMap</b> dan <b>WeakSet</b> hanya menerima <b>object (atau symbol non-registered) sebagai key/nilai</b> dan memegangnya secara <b>lemah</b> (weak reference): jika tidak ada referensi lain ke object itu, <b>garbage collector</b> boleh menghapusnya, dan entri di WeakMap ikut hilang. Ini mencegah <b>memory leak</b>.',
     'Konsekuensinya, WeakMap/WeakSet <b>tidak bisa diiterasi</b> dan tidak punya <code>size</code>; isinya bergantung pada kapan GC berjalan. Metode yang tersedia hanya <code>get/set/has/delete</code> (WeakMap) dan <code>add/has/delete</code> (WeakSet).',
     'Pemakaian nyata: menyimpan <b>data privat atau metadata</b> untuk object milik pihak lain (misalnya elemen DOM) tanpa memodifikasinya, <b>cache/memoization</b> per object yang otomatis bersih, dan menandai object yang sudah diproses (WeakSet) agar tidak diproses dua kali.'],
    "const cache = new WeakMap();\nfunction hitungBerat(obj) {\n  if (cache.has(obj)) return cache.get(obj) + ' (dari cache)';\n  const hasil = obj.items.reduce((a, b) => a + b, 0);\n  cache.set(obj, hasil);\n  return hasil;\n}\nlet laporan = { items: [3, 4, 5] };\nconsole.log(hitungBerat(laporan));\nconsole.log(hitungBerat(laporan));\nlaporan = null;   // tidak ada referensi lagi: entri boleh dibersihkan GC\n\nconst sudahDikirim = new WeakSet();\nfunction kirimEmail(user) {\n  if (sudahDikirim.has(user)) return `lewati ${user.email}`;\n  sudahDikirim.add(user);\n  return `kirim ke ${user.email}`;\n}\nconst u = { email: 'rina@contoh.id' };\nconsole.log(kirimEmail(u), '|', kirimEmail(u));\n\ntry { new WeakMap().set('teks', 1); } catch (e) { console.log(e.name + ':', e.message); }\nconsole.log(typeof new WeakMap().size, Symbol.iterator in new WeakMap());",
    tb=[{'c': 'Map vs WeakMap', 'h': ['Aspek', 'Map', 'WeakMap'], 'r': [
      ['Tipe key', 'Apa saja', 'Hanya object (dan symbol non-registered)'], ['Referensi ke key', 'Kuat: mencegah GC', 'Lemah: tidak mencegah GC'], ['Iterasi, size, clear', 'Ada', 'Tidak ada'],
      ['Risiko memory leak', 'Ada jika lupa delete', 'Rendah'], ['Pemakaian', 'Kamus umum', 'Metadata/cache per object, data privat']]}],
    pts=['Weak = tidak menghalangi garbage collection.', 'Key/nilai harus object.', 'Tidak bisa diiterasi, tidak ada size.', 'Cocok untuk cache per object dan metadata DOM.'],
    qs=[q('Kenapa WeakMap tidak punya size?', ['Isinya bisa hilang kapan saja saat GC berjalan', 'Karena lebih lambat', 'Karena hanya menyimpan satu entri'], 0, 'Jumlahnya tidak deterministik.'),
        q('Key yang ditolak WeakMap?', ["'teks'", '{}', '[]'], 0, 'Primitif string tidak bisa jadi key WeakMap.')]),
  J('JSON',
    ['<b>JSON</b> (JavaScript Object Notation) adalah format teks untuk pertukaran data, dipakai hampir semua REST API, file konfigurasi (package.json), dan penyimpanan seperti localStorage. Sintaksnya lebih ketat dari object JS: key wajib kutip dua, string kutip dua, tidak ada koma di akhir, tidak ada komentar, dan nilai hanya string, number, boolean, null, array, atau object.',
     '<code>JSON.stringify(nilai, replacer, spasi)</code> mengubah nilai menjadi teks. Yang <b>hilang atau berubah</b>: undefined, fungsi, dan symbol dibuang (di array menjadi null), Date menjadi string ISO, Map/Set menjadi <code>{}</code>, NaN/Infinity menjadi null, dan BigInt melempar TypeError. Object bisa mengatur bentuk JSON-nya dengan metode <code>toJSON()</code>.',
     '<code>JSON.parse(teks, reviver)</code> mengubah teks menjadi nilai; teks tidak valid melempar <code>SyntaxError</code>, jadi selalu bungkus dengan try/catch saat datanya dari luar. Parameter <b>reviver</b> berguna untuk menghidupkan kembali tanggal. Ingat, JSON hanya data: jangan pernah memakai <code>eval</code> untuk mengurai JSON.'],
    "const pesanan = {\n  id: 101,\n  pelanggan: 'Dewi',\n  item: [{ sku: 'KP-01', qty: 2 }],\n  dibuat: new Date(Date.UTC(2026, 10, 20, 2, 30)),\n  catatan: undefined,\n  hitung() { return 1; },\n  tag: new Set(['promo']),\n};\nconst teks = JSON.stringify(pesanan);\nconsole.log(teks);\nconsole.log(JSON.stringify({ a: 1, b: [1, 2] }, null, 2));\nconsole.log(JSON.stringify(pesanan, ['id', 'pelanggan']));     // replacer: pilih key\n\nconst balik = JSON.parse(teks, (k, v) => (k === 'dibuat' ? new Date(v) : v));\nconsole.log(balik.dibuat instanceof Date, balik.dibuat.getUTCHours());\n\ntry {\n  JSON.parse(\"{ nama: 'Dewi' }\");\n} catch (e) {\n  console.log(e.name, '-', e.message.split('\\n')[0]);\n}\nconsole.log(JSON.stringify({ n: NaN, x: [undefined, () => 1] }));\nconst rupiah = { nilai: 15000, toJSON() { return `Rp${this.nilai}`; } };\nconsole.log(JSON.stringify({ harga: rupiah }));",
    tb=[{'c': 'Apa yang terjadi saat JSON.stringify', 'h': ['Nilai JS', 'Di dalam object', 'Di dalam array'], 'r': [
      ['undefined, fungsi, symbol', 'Key dibuang', 'Menjadi null'], ['NaN, Infinity', 'null', 'null'], ['Date', 'String ISO (toJSON)', 'String ISO'],
      ['Map, Set', '{}', '{}'], ['BigInt', 'TypeError', 'TypeError'], ['Object dengan toJSON()', 'Hasil toJSON', 'Hasil toJSON']]}],
    pts=['JSON: key dan string kutip dua, tanpa komentar dan koma akhir.', 'stringify membuang undefined/fungsi dan mengubah Date ke string.', 'parse dalam try/catch; reviver untuk tanggal.', 'Jangan pernah eval untuk JSON.'],
    qs=[q('Hasil JSON.stringify({a: undefined, b: 1})?', ['{"b":1}', '{"a":null,"b":1}', '{"a":undefined,"b":1}'], 0, 'Properti undefined dibuang.'),
        q("JSON.parse(\"{'a': 1}\") menghasilkan?", ['SyntaxError', '{a: 1}', 'null'], 0, 'JSON wajib memakai kutip dua.')],
    so=[SX('Simpan keranjang <code>[{nama:"Kopi", qty:2}]</code> sebagai teks JSON (seperti ke localStorage), lalu baca kembali dan tambahkan qty. Tangani juga teks rusak <code>"[{nama:"</code> dengan nilai default array kosong.', 'Buat fungsi bacaAman(teks) dengan try/catch.',
           "const simpan = JSON.stringify([{ nama: 'Kopi', qty: 2 }]);\nconsole.log('disimpan:', simpan);\nfunction bacaAman(teks) {\n  try {\n    return JSON.parse(teks);\n  } catch {\n    return [];\n  }\n}\nconst keranjang = bacaAman(simpan);\nkeranjang[0].qty += 1;\nconsole.log(keranjang);\nconsole.log(bacaAman('[{nama:'));")]),
]),

M('Equality: ==, ===, dan Object.is', 'Menengah',
  'Perbandingan longgar dan ketat, Object.is, serta algoritma IsLooselyEqual, IsStrictlyEqual, SameValue, dan SameValueZero.',
  ['Equality Comparisons', '==', '===', 'Object.is', 'Value Comparison Operators', 'isLooselyEqual', 'isStrictlyEqual', 'SameValueZero'], [
  J('== versus ===',
    ['<code>===</code> (<b>strict equality</b>, algoritma <b>IsStrictlyEqual</b>) membandingkan tanpa konversi: tipe berbeda langsung false. <code>==</code> (<b>loose equality</b>, algoritma <b>IsLooselyEqual</b>) mengonversi tipe lebih dulu dengan aturan yang rumit.',
     'Ringkasan aturan <code>==</code>: null dan undefined hanya sama satu sama lain; number vs string, string diubah ke number; boolean selalu diubah ke number lebih dulu (sehingga <code>"true" == true</code> justru false); object vs primitif, object diubah ke primitif. NaN tidak sama dengan apa pun, termasuk dirinya sendiri.',
     'Standar industri: <b>selalu pakai === dan !==</b> (aturan ESLint <code>eqeqeq</code>). Satu-satunya pengecualian yang sering diterima adalah <code>x == null</code> untuk mengecek null atau undefined sekaligus. Object, array, dan fungsi dibandingkan <b>berdasarkan referensi</b> pada kedua operator: dua object dengan isi sama tetap tidak sama.'],
    "const kasus = [\n  [1, '1'], [0, ''], [0, '0'], ['', '0'], [null, undefined], [null, 0],\n  [false, 'false'], [true, 'true'], [true, '1'], [NaN, NaN], [[1], 1], [[], false],\n];\nconsole.log('a'.padEnd(10), 'b'.padEnd(11), '==    ===');\nfor (const [a, b] of kasus) {\n  const tampil = v => (typeof v === 'string' ? `'${v}'` : Array.isArray(v) ? `[${v}]` : String(v));\n  console.log(tampil(a).padEnd(10), tampil(b).padEnd(11), String(a == b).padEnd(5), a === b);\n}\nconst p1 = { id: 1 }, p2 = { id: 1 }, p3 = p1;\nconsole.log(p1 === p2, p1 == p2, p1 === p3);\nconst input = undefined;\nconsole.log(input == null, input === null);",
    tb=[{'c': 'Aturan IsLooselyEqual (==) secara ringkas', 'h': ['Pasangan tipe', 'Yang dilakukan'], 'r': [
      ['Tipe sama', 'Sama seperti ==='], ['null dan undefined', 'true (dan tidak sama dengan nilai lain)'], ['number dan string', 'String diubah ke number'],
      ['boolean dan apa saja', 'Boolean diubah ke number (true = 1)'], ['object dan primitif', 'Object diubah dengan ToPrimitive'], ['bigint dan string/number', 'Dibandingkan sebagai nilai matematis'], ['NaN', 'Selalu false']]}],
    pts=['=== tanpa konversi; == dengan koersi.', 'Pakai === (eqeqeq); x == null pengecualian yang umum.', 'Object dibandingkan berdasarkan referensi.', 'NaN tidak sama dengan dirinya.'],
    qs=[q("Hasil 'true' == true?", ['false', 'true', 'TypeError'], 0, 'true diubah ke 1, "true" diubah ke NaN.'),
        q('Hasil null == 0?', ['false', 'true', 'undefined'], 0, 'null hanya == undefined.'),
        q('Hasil [] == false?', ['true', 'false', 'TypeError'], 0, 'false -> 0, [] -> "" -> 0.')]),
  J('Object.is, SameValue, dan SameValueZero',
    ['Selain == dan ===, spesifikasi punya dua algoritma kesetaraan lain. <b>SameValue</b> dipakai oleh <code>Object.is(a, b)</code>: sama seperti === kecuali <code>NaN</code> dianggap sama dengan NaN, dan <code>+0</code> dibedakan dari <code>-0</code>.',
     '<b>SameValueZero</b> sama dengan SameValue kecuali +0 dan -0 dianggap sama. Algoritma inilah yang dipakai <code>Array.prototype.includes</code>, key <code>Map</code>, dan nilai <code>Set</code>. Sementara <code>indexOf</code> dan <code>lastIndexOf</code> memakai === sehingga tidak bisa menemukan NaN.',
     'Dalam praktik, Object.is dipakai pustaka seperti <b>React</b> untuk memutuskan apakah state berubah (<code>useState</code>, dependency <code>useEffect</code>, <code>useMemo</code>). Karena perbandingannya per referensi, memutasi object lalu men-set object yang sama tidak memicu render ulang; buat object baru.'],
    "console.log(NaN === NaN, Object.is(NaN, NaN));\nconsole.log(0 === -0, Object.is(0, -0));\nconsole.log([NaN].includes(NaN), [NaN].indexOf(NaN));     // SameValueZero vs ===\nconsole.log([-0].includes(0), new Set([0, -0]).size);\nconst m = new Map([[NaN, 'bukan angka']]);\nconsole.log(m.get(NaN));\nconsole.log(1 / 0, 1 / -0);                               // kenapa -0 bisa penting\n\n// cara kerja seperti React: bandingkan state lama dan baru dengan Object.is\nfunction setState(lama, baru) {\n  return Object.is(lama, baru) ? 'tidak render ulang' : 'render ulang';\n}\nconst state = { items: [1] };\nstate.items.push(2);\nconsole.log(setState(state, state));                     // mutasi: referensi sama\nconsole.log(setState(state, { ...state, items: [...state.items, 3] }));",
    tb=[{'c': 'Empat algoritma kesetaraan', 'h': ['Algoritma', 'Dipakai oleh', 'NaN vs NaN', '+0 vs -0', 'Konversi tipe'], 'r': [
      ['IsLooselyEqual', '==', 'false', 'sama', 'Ya'], ['IsStrictlyEqual', '===, indexOf, switch', 'false', 'sama', 'Tidak'],
      ['SameValueZero', 'includes, Map, Set', 'sama', 'sama', 'Tidak'], ['SameValue', 'Object.is, React', 'sama', 'beda', 'Tidak']]}],
    pts=['Object.is = SameValue: NaN sama, +0 beda -0.', 'includes, Map, Set = SameValueZero.', 'indexOf dan switch memakai ===.', 'React membandingkan state dengan Object.is: jangan mutasi.'],
    qs=[q('Metode yang bisa menemukan NaN di array?', ['includes', 'indexOf', 'lastIndexOf'], 0, 'includes memakai SameValueZero.'),
        q('Object.is(0, -0)?', ['false', 'true', 'NaN'], 0, 'SameValue membedakan tanda nol.')],
    so=[SX('Tulis fungsi <code>samaDangkal(a, b)</code> yang membandingkan dua object satu tingkat memakai Object.is untuk setiap key (seperti shallowEqual di React). Uji dengan tiga pasangan.', 'Cek jumlah key sama, lalu every key Object.is(a[k], b[k]).',
           "function samaDangkal(a, b) {\n  if (Object.is(a, b)) return true;\n  const ka = Object.keys(a), kb = Object.keys(b);\n  return ka.length === kb.length && ka.every(k => Object.hasOwn(b, k) && Object.is(a[k], b[k]));\n}\nconst list = [1];\nconsole.log(samaDangkal({ x: 1, y: NaN }, { x: 1, y: NaN }));\nconsole.log(samaDangkal({ a: list }, { a: list }));\nconsole.log(samaDangkal({ a: [1] }, { a: [1] }));")]),
]),
]
